@startuml

class SensorController {
  + systemName : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalPowerConsumption : float
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + systemName : string
}

class AlertMessage {
  + content : string
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Inhabitant "*" -- "1" Apartment
Inhabitant "1" -- "1" SensorController
Inhabitant "0..1" -- "1" SensorController : administrator
Sensor "1" -- "1..*" SensorValue
Sensor "1" -- "0..1" SensorValue : lastValue
SensorController "1" -- "1..*" Sensor
EMonitor "1" -- "1" SensorController : attachedTo
EMonitor "1" -- "1..*" AlertMessage
AlertMessage "1" -- "1" SensorController : sentVia
SensorController "1" -- "0..1" string : emailAddress

TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

